 from "@/app/_lib/subscription";
import { assessLateFee } from "@/app/_lib/late-fees/assess";
import { formatCents } from "@/app/_lib/format";
import { appendQuickbooksInvoiceNote } from "@/app/_lib/integrations/quickbooks-writeback";
import { writeBackChaseNote } from "@/app/_lib/integrations/xero-sync";
import { DEMO_EMAIL } from "@/app/_lib/demo";
import type { Invoice, LateFeePolicy } from "@/app/_lib/types";

export const runtime = "nodejs";
export const maxDuration = 300;
export const dynamic = "force-dynamic";

// Late-fee assessment (Vercel cron — see vercel.json, 0 14 * * *). For every
// Pro user with an ENABLED late-fee policy, re-assesses each open/overdue/
// partial invoice with the deterministic calculator (_lib/late-fees/assess.ts —
// policy clamped to the state ceiling) and writes late_fee_cents /
// late_fee_applied_at when the computed fee INCREASED — the fee ratchets up
// month by month and never bounces down; a waived fee is never re-applied.
// External invoices get the fee mirrored into their books off the critical
// path: a QBO PrivateNote line / Xero History record.
//
// Gated on CRON_SECRET — Vercel Cron sends `Authorization: Bearer <CRON_SECRET>`.
// Pass ?userId=<uid> to scope one user.

const ASSESSABLE: ReadonlyArray<Invoice["status"]> = ["open", "overdue", "partial"];

function authorized(req: NextRequest): boolean {
  const secret = process.env.CRON_SECRET;
  if (!secret) return false;
  return req.headers.get("authorization") === `Bearer ${secret}`;
}

async function handle(req: NextRequest) {
  if (!authorized(req)) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  }
  const onlyUserId = req.nextUrl.searchParams.get("userId") ?? undefined;

  const sb = adminSupabase();

  // Skip the shared demo account — its fee is seeded, never assessed.
  const demoId = onlyUserId
    ? null
    : (await sb.auth.admin.listUsers({ page: 1, perPage: 200 })).data?.users.find(
        (u) => u.email === DEMO_EMAIL,
      )?.id ?? null;

  let pq = sb.from("invoices_late_fee_policy").select("*").eq("enabled", true);
  if (onlyUserId) pq = pq.eq("user_id", onlyUserId);
  const { data: policies, error } = await pq;
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  const now = new Date();
  const nowIso = now.toISOString();
  let considered = 0;
  let applied = 0;
  const perUser: Array<{ userId: string; applied: number }> = [];

  for (const raw of policies ?? []) {
    const policy = raw as LateFeePolicy;
    const userId = policy.user_id;
    if (!userId || (demoId && userId === demoId)) continue;

    // Late-fee automation is Pro labor — free users' policies stay dormant.
    if ((await getUserTier(userId)) !== "pro") continue;

    const { data: invRows } = await sb
      .from("invoices_invoices")
      .select("*")
      .eq("user_id", userId)
      .in("status", ASSESSABLE as string[])
      .eq("late_fee_waived", false)
      .not("due_date", "is", null);

    let userApplied = 0;
    for (const inv of (invRows ?? []) as Invoice[]) {
      considered++;
      const fee = assessLateFee(inv, policy, now);
      // Ratchet: write only when the assessed fee EXCEEDS what's on the row.
      if (fee <= Number(inv.late_fee_cents ?? 0)) continue;

      const { error: upErr } = await sb
        .from("invoices_invoices")
        .update({
          late_fee_cents: fee,
          late_fee_applied_at: nowIso,
          updated_at: nowIso,
          // A cached Stripe Payment Link was minted at the OLD total; clear it
          // so the next reminder creates a fresh link that collects the new
          // balance (link amount must always match the reminder copy).
          payment_link_url: null,
        })
        .eq("user_id", userId)
        .eq("id", inv.id)
        .eq("late_fee_waived", false);
      if (upErr) continue;
      userApplied++;
      applied++;

      // Mirror the fee into the books (internal notes only, never the ledger)
      // — best-effort, off the critical path.
      if (inv.external_id) {
        const line = `Late fee of ${formatCents(fee)} applied ${nowIso.slice(0, 10)} per your late-fee policy`;
        const extId = inv.external_id;
        if (inv.external_source === "quickbooks") {
          after(() => appendQuickbooksInvoiceNote(sb, userId, extId, line));
        } else if (inv.external_source === "xero") {
          after(() => writeBackChaseNote(userId, extId, line));
        }
      }
    }

    if (userApplied > 0) {
      revalidateUser("invoices", ["invoices"], userId);
      perUser.push({ userId, applied: userApplied });
    }
  }

  return NextResponse.json({ ok: true, considered, applied, users: perUser });
}

export const GET = handle;
export const POST = handle;
