import { NextResponse, type NextRequest } from "next/server";
import { requireActor } from "@/app/_lib/firm/actor";
import { adminSupabase } from "@/app/_lib/supabase/admin";
import { isDemoEmail, DEMO_READONLY_MESSAGE } from "@/app/_lib/demo";
import { requirePro } from "@/app/_lib/subscription";
import { clampPolicyToState, stateRule } from "@/app/_lib/late-fees/state-rules";
import { POLICY_DEFAULTS } from "@/app/_lib/late-fees/assess";
import type { LateFeePolicy } from "@/app/_lib/types";

export const runtime = "nodejs";

// Late-fee policy — GET returns the user's policy (defaults when none is saved
// yet) plus the resolved state rule; PUT validates, clamps to the state's
// ceiling (clampPolicyToState), and upserts. ENABLING the policy is Pro labor
// (the assessment cron only runs for Pro anyway), so a free PUT with
// enabled:true gets the standard 402 the UI turns into the upgrade modal —
// saving a disabled draft is free.

export async function GET() {
  const actor = await requireActor();
  if (!actor) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const { authUser: user, ownerId } = actor;

  const sb = adminSupabase();
  const { data } = await sb
    .from("invoices_late_fee_policy")
    .select("*")
    .eq("user_id", ownerId)
    .maybeSingle();

  const policy: LateFeePolicy = (data as LateFeePolicy) ?? {
    user_id: ownerId,
    ...POLICY_DEFAULTS,
  };
  return NextResponse.json({ policy, stateRule: stateRule(policy.state_code) });
}

export async function PUT(req: NextRequest) {
  const actor = await requireActor();
  if (!actor) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const { authUser: user, ownerId } = actor;
  if (isDemoEmail(user.email)) {
    return NextResponse.json({ error: DEMO_READONLY_MESSAGE }, { status: 403 });
  }

  const body = (await req.json().catch(() => ({}))) as Partial<LateFeePolicy>;

  const enabled = body.enabled === true;
  if (enabled) {
    const gate = await requirePro(ownerId);
    if (!gate.allowed) {
      return NextResponse.json(
        {
          error:
            "Automatic late fees are a Pro feature. Upgrade to have FetchDue assess and apply them for you.",
          reason: gate.reason,
        },
        { status: 402 },
      );
    }
  }

  const rawState = typeof body.state_code === "string" ? body.state_code.trim().toUpperCase() : null;
  const stateCode = rawState && stateRule(rawState) ? rawState : null;
  if (rawState && !stateCode) {
    return NextResponse.json({ error: "Unknown state code." }, { status: 400 });
  }

  const clamped = clampPolicyToState(
    {
      grace_days: body.grace_days ?? POLICY_DEFAULTS.grace_days,
      mode: body.mode === "flat" ? "flat" : "percent_monthly",
      percent_bp: body.percent_bp ?? POLICY_DEFAULTS.percent_bp,
      flat_cents: body.flat_cents ?? POLICY_DEFAULTS.flat_cents,
      max_total_bp: body.max_total_bp ?? POLICY_DEFAULTS.max_total_bp,
    },
    stateCode,
  );

  const sb = adminSupabase();
  const row = {
    user_id: ownerId,
    enabled,
    ...clamped,
    state_code: stateCode,
    apply_to: "all",
    updated_at: new Date().toISOString(),
  };
  const { error } = await sb
    .from("invoices_late_fee_policy")
    .upsert(row, { onConflict: "user_id" });
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  return NextResponse.json({ ok: true, policy: row, stateRule: stateRule(stateCode) });
}
